
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_kcis_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_kcis", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.882977840385447e-02, -4.837482338826541e-02, -4.771790035962991e-02, -4.676795699046105e-02, -4.539194884271710e-02, -4.339637059848710e-02, -4.050826663001483e-02, -3.638927830377319e-02, -3.083542619740422e-02, -2.465001461007641e-02, -2.269317799305618e-02, -4.015681856525821e-02, -4.127208020823859e-02, -2.632368557174717e-02, -1.609024771051146e-02, -7.151869974590713e-03, -1.816837336230391e-03, -2.053914770514364e-04, -3.953364657263548e-06, -1.359273879065376e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


